CREATE OR REPLACE FUNCTION public.is_assurance_staff(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_uid AND role IN ('admin','reviewer')) $$;
CREATE OR REPLACE FUNCTION public.owns_listing(_listing uuid, _uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT EXISTS(SELECT 1 FROM public.listings WHERE id=_listing AND owner_id=_uid) $$;

CREATE TABLE public.organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, org_type text NOT NULL CHECK (org_type IN ('res360','landlord','manager','institution','auditor')), registration_number text, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.organization_memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, user_id uuid NOT NULL, member_role text NOT NULL DEFAULT 'member', status text NOT NULL DEFAULT 'active', invited_by uuid, accepted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,user_id));
ALTER TABLE public.listings ADD COLUMN IF NOT EXISTS organization_id uuid REFERENCES public.organizations(id), ADD COLUMN IF NOT EXISTS assurance_state text NOT NULL DEFAULT 'not_checked', ADD COLUMN IF NOT EXISTS last_audited_at timestamptz, ADD COLUMN IF NOT EXISTS next_review_at timestamptz;

CREATE TABLE public.provider_verifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid REFERENCES public.organizations(id), listing_id uuid REFERENCES public.listings(id), verification_type text NOT NULL, subject_name text, source_authority text NOT NULL, reference_last4 text, status text NOT NULL DEFAULT 'pending', checked_by uuid, checked_at timestamptz, valid_from date, expires_at date, method text, notes_restricted text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.evidence_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), listing_id uuid NOT NULL REFERENCES public.listings(id), verification_id uuid REFERENCES public.provider_verifications(id), document_type text NOT NULL, issuer text, reference_masked text, issued_at date, expires_at date, storage_key text NOT NULL, sha256 text, scan_status text NOT NULL DEFAULT 'pending', uploaded_by uuid NOT NULL DEFAULT auth.uid(), review_status text NOT NULL DEFAULT 'pending', reviewer_id uuid, reviewed_at timestamptz, retention_until date, access_class text NOT NULL DEFAULT 'restricted', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.audit_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, property_type text, jurisdiction_scope text, version integer NOT NULL DEFAULT 1, effective_from date, effective_to date, source_refs text[] NOT NULL DEFAULT '{}', published_by uuid, published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(name,version));
CREATE TABLE public.audit_template_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), template_id uuid NOT NULL REFERENCES public.audit_templates(id) ON DELETE CASCADE, section text NOT NULL, item_code text NOT NULL, label text NOT NULL, guidance text, severity_if_failed text NOT NULL DEFAULT 'medium' CHECK (severity_if_failed IN ('low','medium','high','critical')), weight numeric NOT NULL DEFAULT 1, required_evidence_types text[] NOT NULL DEFAULT '{}', critical_gate boolean NOT NULL DEFAULT false, sort_order integer NOT NULL DEFAULT 0, UNIQUE(template_id,item_code));
CREATE TABLE public.audits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), listing_id uuid NOT NULL REFERENCES public.listings(id), template_id uuid NOT NULL REFERENCES public.audit_templates(id), template_version integer NOT NULL, audit_type text NOT NULL CHECK (audit_type IN ('desktop','onsite','follow_up','complaint')), status text NOT NULL DEFAULT 'scheduled', scheduled_at timestamptz, started_at timestamptz, submitted_at timestamptz, auditor_id uuid, reviewer_id uuid, location_accuracy_m numeric, device_captured_at timestamptz, server_received_at timestamptz DEFAULT now(), decision text, decision_reason text, next_due_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.audit_responses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), audit_id uuid NOT NULL REFERENCES public.audits(id) ON DELETE CASCADE, template_item_id uuid NOT NULL REFERENCES public.audit_template_items(id), result text NOT NULL CHECK (result IN ('pass','fail','not_applicable','not_observed')), severity text, notes text, evidence_ids uuid[] NOT NULL DEFAULT '{}', observed_at timestamptz, created_by uuid NOT NULL DEFAULT auth.uid(), review_status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(audit_id,template_item_id));
CREATE TABLE public.corrective_actions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), listing_id uuid NOT NULL REFERENCES public.listings(id), audit_id uuid REFERENCES public.audits(id), audit_response_id uuid REFERENCES public.audit_responses(id), title text NOT NULL, severity text NOT NULL CHECK (severity IN ('low','medium','high','critical')), owner_user_id uuid, status text NOT NULL DEFAULT 'open', due_at timestamptz, provider_response text, submitted_resolution_at timestamptz, verified_closed_at timestamptz, closure_reviewer_id uuid, reopen_count integer NOT NULL DEFAULT 0, public_disclosure_level text NOT NULL DEFAULT 'none', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.safety_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), listing_id uuid REFERENCES public.listings(id), reporter_user_id uuid DEFAULT auth.uid(), category text NOT NULL CHECK (category IN ('urgent_danger','fire_electrical','water_sanitation','overcrowding','harassment_threat','billing_lease','accessibility','other')), urgency text NOT NULL DEFAULT 'normal' CHECK (urgency IN ('critical','high','normal')), description text NOT NULL CHECK (length(description) BETWEEN 10 AND 4000), anonymous_to_landlord boolean NOT NULL DEFAULT true, occurred_at timestamptz, reported_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'new', assigned_to uuid, acknowledged_at timestamptz, closed_at timestamptz, retention_until date);
CREATE TABLE public.report_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), safety_report_id uuid NOT NULL REFERENCES public.safety_reports(id) ON DELETE CASCADE, actor_id uuid NOT NULL DEFAULT auth.uid(), event_type text NOT NULL, note text, visibility text NOT NULL DEFAULT 'staff' CHECK (visibility IN ('staff','reporter')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.utility_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), listing_id uuid NOT NULL REFERENCES public.listings(id), utility_type text NOT NULL CHECK (utility_type IN ('electricity','water','internet','other')), started_at timestamptz NOT NULL, ended_at timestamptz, source text NOT NULL CHECK (source IN ('provider','manager','students','auditor')), confidence text NOT NULL DEFAULT 'unconfirmed', public_summary text, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.alerts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recipient_user_id uuid NOT NULL, listing_id uuid REFERENCES public.listings(id), event_type text NOT NULL, severity text NOT NULL DEFAULT 'normal', channel text NOT NULL DEFAULT 'in_app', payload jsonb NOT NULL DEFAULT '{}', dedupe_key text UNIQUE, delivery_status text NOT NULL DEFAULT 'pending', sent_at timestamptz, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.audit_log(id bigserial PRIMARY KEY, actor_id uuid, resource_type text NOT NULL, resource_id uuid, action text NOT NULL, before_data jsonb, after_data jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.consents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), purpose_code text NOT NULL, notice_version text NOT NULL, granted_at timestamptz NOT NULL DEFAULT now(), withdrawn_at timestamptz);

GRANT SELECT,INSERT,UPDATE,DELETE ON public.organizations,public.organization_memberships,public.provider_verifications,public.evidence_documents,public.audit_templates,public.audit_template_items,public.audits,public.audit_responses,public.corrective_actions,public.safety_reports,public.report_events,public.utility_events,public.alerts,public.consents TO authenticated;
GRANT SELECT ON public.audit_log TO authenticated;
GRANT ALL ON public.organizations,public.organization_memberships,public.provider_verifications,public.evidence_documents,public.audit_templates,public.audit_template_items,public.audits,public.audit_responses,public.corrective_actions,public.safety_reports,public.report_events,public.utility_events,public.alerts,public.consents,public.audit_log TO service_role;
GRANT USAGE ON SEQUENCE public.audit_log_id_seq TO service_role;

DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['organizations','organization_memberships','provider_verifications','evidence_documents','audit_templates','audit_template_items','audits','audit_responses','corrective_actions','safety_reports','report_events','utility_events','alerts','audit_log','consents'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); END LOOP; END $$;

CREATE POLICY "staff all orgs" ON public.organizations FOR ALL TO authenticated USING (public.is_assurance_staff(auth.uid())) WITH CHECK (public.is_assurance_staff(auth.uid()));
CREATE POLICY "members read org" ON public.organizations FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.organization_memberships m WHERE m.organization_id=organizations.id AND m.user_id=auth.uid()));
CREATE POLICY "staff all memberships" ON public.organization_memberships FOR ALL TO authenticated USING (public.is_assurance_staff(auth.uid())) WITH CHECK (public.is_assurance_staff(auth.uid()));
CREATE POLICY "own memberships" ON public.organization_memberships FOR SELECT TO authenticated USING (user_id=auth.uid());

CREATE POLICY "staff all verifications" ON public.provider_verifications FOR ALL TO authenticated USING (public.is_assurance_staff(auth.uid())) WITH CHECK (public.is_assurance_staff(auth.uid()));
CREATE POLICY "owner reads verifications" ON public.provider_verifications FOR SELECT TO authenticated USING (listing_id IS NOT NULL AND public.owns_listing(listing_id,auth.uid()));

CREATE POLICY "staff all evidence" ON public.evidence_documents FOR ALL TO authenticated USING (public.is_assurance_staff(auth.uid())) WITH CHECK (public.is_assurance_staff(auth.uid()));
CREATE POLICY "owner reads evidence" ON public.evidence_documents FOR SELECT TO authenticated USING (public.owns_listing(listing_id,auth.uid()));
CREATE POLICY "owner uploads evidence" ON public.evidence_documents FOR INSERT TO authenticated WITH CHECK (public.owns_listing(listing_id,auth.uid()) AND uploaded_by=auth.uid() AND review_status='pending');

CREATE POLICY "auth read templates" ON public.audit_templates FOR SELECT TO authenticated USING (true);
CREATE POLICY "staff manage templates" ON public.audit_templates FOR ALL TO authenticated USING (public.is_assurance_staff(auth.uid())) WITH CHECK (public.is_assurance_staff(auth.uid()));
CREATE POLICY "auth read template items" ON public.audit_template_items FOR SELECT TO authenticated USING (true);
CREATE POLICY "staff manage template items" ON public.audit_template_items FOR ALL TO authenticated USING (public.is_assurance_staff(auth.uid())) WITH CHECK (public.is_assurance_staff(auth.uid()));

CREATE POLICY "staff all audits" ON public.audits FOR ALL TO authenticated USING (public.is_assurance_staff(auth.uid())) WITH CHECK (public.is_assurance_staff(auth.uid()));
CREATE POLICY "auditor reads assigned" ON public.audits FOR SELECT TO authenticated USING (auditor_id=auth.uid());
CREATE POLICY "auditor updates assigned" ON public.audits FOR UPDATE TO authenticated USING (auditor_id=auth.uid() AND status IN ('scheduled','in_progress')) WITH CHECK (auditor_id=auth.uid() AND decision IS NULL);
CREATE POLICY "owner reads audits" ON public.audits FOR SELECT TO authenticated USING (public.owns_listing(listing_id,auth.uid()));

CREATE POLICY "staff all responses" ON public.audit_responses FOR ALL TO authenticated USING (public.is_assurance_staff(auth.uid())) WITH CHECK (public.is_assurance_staff(auth.uid()));
CREATE POLICY "auditor writes responses" ON public.audit_responses FOR ALL TO authenticated USING (EXISTS(SELECT 1 FROM public.audits a WHERE a.id=audit_responses.audit_id AND a.auditor_id=auth.uid() AND a.status IN ('scheduled','in_progress'))) WITH CHECK (EXISTS(SELECT 1 FROM public.audits a WHERE a.id=audit_responses.audit_id AND a.auditor_id=auth.uid() AND a.status IN ('scheduled','in_progress')));
CREATE POLICY "owner reads responses" ON public.audit_responses FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.audits a WHERE a.id=audit_responses.audit_id AND public.owns_listing(a.listing_id,auth.uid())));

CREATE POLICY "staff all actions" ON public.corrective_actions FOR ALL TO authenticated USING (public.is_assurance_staff(auth.uid())) WITH CHECK (public.is_assurance_staff(auth.uid()));
CREATE POLICY "owner reads actions" ON public.corrective_actions FOR SELECT TO authenticated USING (public.owns_listing(listing_id,auth.uid()));

CREATE POLICY "staff all reports" ON public.safety_reports FOR ALL TO authenticated USING (public.has_role(auth.uid(),'safety_manager') OR public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'safety_manager') OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "student submits report" ON public.safety_reports FOR INSERT TO authenticated WITH CHECK (reporter_user_id=auth.uid() AND status='new' AND assigned_to IS NULL);
CREATE POLICY "student reads own report" ON public.safety_reports FOR SELECT TO authenticated USING (reporter_user_id=auth.uid());
CREATE POLICY "staff all report events" ON public.report_events FOR ALL TO authenticated USING (public.has_role(auth.uid(),'safety_manager') OR public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'safety_manager') OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "reporter reads shared events" ON public.report_events FOR SELECT TO authenticated USING (visibility='reporter' AND EXISTS(SELECT 1 FROM public.safety_reports r WHERE r.id=report_events.safety_report_id AND r.reporter_user_id=auth.uid()));

CREATE POLICY "staff all utility" ON public.utility_events FOR ALL TO authenticated USING (public.is_assurance_staff(auth.uid())) WITH CHECK (public.is_assurance_staff(auth.uid()));
CREATE POLICY "owner manages utility" ON public.utility_events FOR ALL TO authenticated USING (public.owns_listing(listing_id,auth.uid())) WITH CHECK (public.owns_listing(listing_id,auth.uid()) AND source='manager');

CREATE POLICY "own alerts read" ON public.alerts FOR SELECT TO authenticated USING (recipient_user_id=auth.uid());
CREATE POLICY "own alerts mark read" ON public.alerts FOR UPDATE TO authenticated USING (recipient_user_id=auth.uid()) WITH CHECK (recipient_user_id=auth.uid());
CREATE POLICY "staff read audit log" ON public.audit_log FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE POLICY "own consents" ON public.consents FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());

CREATE OR REPLACE FUNCTION public.listing_assurance(_listing uuid) RETURNS TABLE(assurance_state text, last_audited_at timestamptz, next_review_at timestamptz, verifications jsonb, open_public_actions integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT l.assurance_state, l.last_audited_at, l.next_review_at,
  coalesce((SELECT jsonb_agg(jsonb_build_object('type',v.verification_type,'authority',v.source_authority,'checked_at',v.checked_at,'expires_at',v.expires_at)) FROM public.provider_verifications v WHERE v.listing_id=l.id AND v.status='confirmed' AND (v.expires_at IS NULL OR v.expires_at>=current_date)),'[]'::jsonb),
  (SELECT count(*)::int FROM public.corrective_actions c WHERE c.listing_id=l.id AND c.status<>'closed' AND c.public_disclosure_level<>'none')
 FROM public.listings l WHERE l.id=_listing AND l.status='approved' $$;
GRANT EXECUTE ON FUNCTION public.listing_assurance(uuid) TO anon, authenticated;

CREATE OR REPLACE FUNCTION public.log_assurance_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN INSERT INTO public.audit_log(actor_id,resource_type,resource_id,action,before_data,after_data) VALUES(auth.uid(),TG_TABLE_NAME,CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END,TG_OP,CASE WHEN TG_OP<>'INSERT' THEN to_jsonb(OLD) END,CASE WHEN TG_OP<>'DELETE' THEN to_jsonb(NEW) END); RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['provider_verifications','evidence_documents','audits','audit_responses','corrective_actions','safety_reports'] LOOP EXECUTE format('CREATE TRIGGER log_%I AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.log_assurance_change()',t,t); END LOOP; END $$;

CREATE OR REPLACE FUNCTION public.set_report_urgency() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.urgency := CASE WHEN NEW.category IN ('urgent_danger','fire_electrical','harassment_threat') THEN 'critical' WHEN NEW.category IN ('water_sanitation','overcrowding') THEN 'high' ELSE 'normal' END; RETURN NEW; END $$;
CREATE TRIGGER report_urgency BEFORE INSERT ON public.safety_reports FOR EACH ROW EXECUTE FUNCTION public.set_report_urgency();

CREATE OR REPLACE FUNCTION public.evidence_path_listing(_name text) RETURNS uuid LANGUAGE plpgsql IMMUTABLE AS $$ BEGIN RETURN split_part(_name,'/',1)::uuid; EXCEPTION WHEN others THEN RETURN NULL; END $$;
CREATE POLICY "evidence owner upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='evidence' AND public.owns_listing(public.evidence_path_listing(name),auth.uid()));
CREATE POLICY "evidence owner or staff read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id='evidence' AND (public.is_assurance_staff(auth.uid()) OR public.owns_listing(public.evidence_path_listing(name),auth.uid())));